import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"SDK 概念","description":"原生 JSON 流程、能力位、适配器、差量 magic、明确不做。","frontmatter":{"title":"SDK 概念","description":"原生 JSON 流程、能力位、适配器、差量 magic、明确不做。"},"headers":[],"relativePath":"api/sdk/concepts.md","filePath":"api/sdk/concepts.md","lastUpdated":1790057721000}`),a={name:`api/sdk/concepts.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="sdk-概念" tabindex="-1">SDK 概念 <a class="header-anchor" href="#sdk-概念" aria-label="Permalink to “SDK 概念”">​</a></h1><p>跨语言进阶说明。语言细节在各语言页。</p><h2 id="范围" tabindex="-1">范围 <a class="header-anchor" href="#范围" aria-label="Permalink to “范围”">​</a></h2><p>封装原生客户端 JSON：检查、下载、校验、可选差量/打包、可选替换。</p><p>明确不做：管理平面 SDK；Sparkle/WinGet/electron-updater/Play/App Store；OpenAPI 生成客户端；浏览器与 Deno（TypeScript 无 browser export）。</p><h2 id="默认流程" tabindex="-1">默认流程 <a class="header-anchor" href="#默认流程" aria-label="Permalink to “默认流程”">​</a></h2><ol><li>调用方传入身份参数（含稳定 <code>device_id</code>）。SDK 不编身份、不把明文设备编号写入日志。</li><li>可选设备报到。</li><li>POST 检查更新（默认能力只有整包）。</li><li>可选更新说明（check 响应不含正文）。</li><li>下载 <code>/packages/{sha256}</code>（保留 <code>exp</code>/<code>sig</code>，支持 Range）。</li><li>SHA-256；若有 <code>signature</code> 则按检查载荷验签。</li><li>有 Replacer 才安装，否则返回已校验暂存路径。</li></ol><h2 id="检查与-http" tabindex="-1">检查与 HTTP <a class="header-anchor" href="#检查与-http" aria-label="Permalink to “检查与 HTTP”">​</a></h2><p>检查更新是 <strong>POST</strong>；GET 同路径 404。204 无更新、304 ETag 命中，都不是失败。错误看 <code>{ &quot;error&quot;: { &quot;code&quot;, &quot;message&quot;, &quot;details&quot; } }</code>。</p><h2 id="能力位" tabindex="-1">能力位 <a class="header-anchor" href="#能力位" aria-label="Permalink to “能力位”">​</a></h2><p>只申报已经接上、真能用的适配器：<code>full_package</code> / <code>file_list</code> / <code>patch_package</code> / <code>binary_delta</code>（加 <code>accepted_delta_algos</code>）。未注入差量应用器时禁止报 <code>binary_delta</code>。<code>local_sha256</code> 只出现在差量请求。</p><h2 id="适配器" tabindex="-1">适配器 <a class="header-anchor" href="#适配器" aria-label="Permalink to “适配器”">​</a></h2><p>HTTP、文件、哈希、zip、验签可注入。JSON <strong>不是</strong>适配器（Java Jackson、Kotlin kotlinx.serialization、Rust serde_json、C cJSON、C++ nlohmann/json 等写死）。不要再叠第二套 HTTP/JSON 库（axios、OkHttp、Guzzle、Gson、RapidJSON 等）。差量 apply 与占用文件/APK 没有默认实现：只留 Patcher / Replacer（Go 可另提供可选纯 Go Patcher）。</p><h2 id="差量-magic" tabindex="-1">差量 magic <a class="header-anchor" href="#差量-magic" aria-label="Permalink to “差量 magic”">​</a></h2><p>不得交叉解码：<code>KVDIFFHP1</code>、<code>HDIFF13&amp;</code>、<code>BSDIFF40</code>、VCDIFF <code>D6 C3 C4</code>。未知 magic 回退整包。见 <a href="/faq/delta">FAQ · 差量</a>。</p><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to “Docker”">​</a></h2><p>SDK 包、安装步骤、调用方应用都不依赖 Docker。契约测试注入假 Transport。Swift <code>swift test</code> 需要 Apple 工具链。</p><h2 id="明确不做" tabindex="-1">明确不做 <a class="header-anchor" href="#明确不做" aria-label="Permalink to “明确不做”">​</a></h2><p>管理平面 SDK；商店 feed 客户端；OpenAPI Generator / hey-api 生成客户端；浏览器 / Deno 更新器；把本服务器仓库的 <code>main</code> 当作 Go/PHP/Swift 包根。</p>`,19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};